using namespace sqlgen;
using namespace sqlgen::literals;

namespace query_course_enrollment_stats {

struct Course {
  PrimaryKey<int> course_id;
  std::string title;
};

struct Enrollment {
  PrimaryKey<int> enrollment_id;
  ForeignKey<int, Course, "course_id"> course_id;
  std::optional<float> grade;
};

struct CourseStats {
  std::string title;
  int student_count;
  std::optional<double> avg_grade;
};

struct CourseStatsView {
  // View to store course enrollment statistics
  std::string title;
  int student_count;
  std::optional<double> avg_grade;
};

/**
 * Function: Calculate enrollment statistics per course.
 * 
 * @return List of course statistics
 */
std::vector<CourseStats> query_course_enrollment_stats() {
  // Connect to the SQLite database
  auto conn = sqlite::connect("test_db.sqlite");

  // Create tables if they don't exist
  conn |= create_table<Course>;
  conn |= create_table<Enrollment>;

  // Perform the query
  auto result = select_from<Course, "c">(
      col<"title">,
      count(col<"enrollment_id">) | as<"student_count">,
      avg(col<"grade">) | as<"avg_grade">
    )
    | left_join<Enrollment, "e">(col<"c", "course_id"> == col<"e", "course_id">)
    | group_by(col<"c", "course_id">, col<"title">)
    | to<std::vector<CourseStatsView>>;

  auto stats = conn |= result;

  // Convert to the required return type
  std::vector<CourseStats> course_stats;
  for (const auto& stat : stats) {
    course_stats.push_back(CourseStats{
      .title = stat.title,
      .student_count = stat.student_count,
      .avg_grade = stat.avg_grade
    });
  }

  return course_stats;
}

}  // namespace query_course_enrollment_stats
