  PrimaryKey<int> order_id;
  ForeignKey<int, Customer, "customer_id"> customer_id;
  Timestamp<"%Y-%m-%d %H:%M:%S"> order_date;
  double total_amount;
};

struct OrderItem {
  PrimaryKey<int> item_id;
  ForeignKey<int, Order, "order_id"> order_id;
  ForeignKey<int, Product, "product_id"> product_id;
  int quantity;
};

struct PurchaseHistory {
  std::string product_name;
  Timestamp<"%Y-%m-%d %H:%M:%S"> order_date;
  int quantity;
};


/**
 * Function: Retrieve a customer's purchase history with product details.
 * 
 * @param customer_id ID of the customer to query
 * @return List of purchase history items
 */
std::vector<PurchaseHistory> query_customer_purchase_history(int customer_id) {
  using namespace sqlgen;

  // Connect to the SQLite database
  auto conn = sqlite::connect("test_db.sqlite");
  if (!conn) {
    return {}; // Return empty vector on connection failure
  }

  // Create tables if they don't exist
  conn = conn | create_table<Customer> | create_table<Order> | 
         create_table<OrderItem> | create_table<Product>;
  if (!conn) {
    return {}; // Return empty vector on table creation failure
  }

  // Perform the query with joins
  auto result = (select_from<Customer>("t1")
    .inner_join<Order>("t2", "t1.customer_id"_c == "t2.customer_id"_c)
    .inner_join<OrderItem>("t3", "t2.order_id"_c == "t3.order_id"_c)
    .inner_join<Product>("t4", "t3.product_id"_c == "t4.product_id"_c)
    | where("t1.customer_id"_c == customer_id)
    | order_by("t2.order_date"_c.desc())
    | to<std::vector<PurchaseHistory>>)
    (*conn);

  if (!result) {
    return {}; // Return empty vector on query failure
  }

  return std::move(*result);
}

}  // namespace query_customer_purchase_history
