#include "sqlgen/to.hpp"

namespace query_product_sales_report {

struct Product {
  PrimaryKey<int> product_id;
  std::string category;
};

struct Sale {
  PrimaryKey<int> sale_id;
  int product_id;
  int quantity;
  double amount;
};

struct CategoryReport {
  std::string category;
  int total_qty;
  double total_amt;
};

struct ProductSalesReport {
  static constexpr const char* tablename = "ProductSalesReport";
  static constexpr bool is_view = true;
  std::string category;
  int total_qty;
  double total_amt;
};

using namespace sqlgen;
using namespace sqlgen::literals;

std::vector<CategoryReport> query_product_sales_report() {
    auto conn = sqlite::connect("test_db.sqlite");

    if (!conn) {
        return {};
    }

    auto result = select_from<Product, "p">(
        col<"category">_t1,
        sum(col<"quantity">_t2).as<"total_qty">(),
        sum(col<"amount">_t2).as<"total_amt">()
    ) 
    | inner_join<Sale, "s">(col<"product_id">_t1 == col<"product_id">_t2)
    | group_by(col<"category">_t1)
    | to<std::vector<CategoryReport>>
    | conn;

    if (result) {
        auto reports = std::move(*result);
        // Filter categories with total sales > 5000
        std::vector<CategoryReport> filtered_reports;
        for (const auto& report : reports) {
            if (report.total_amt > 5000) {
                filtered_reports.push_back(report);
            }
        }
        return filtered_reports;
    }

    return {};
}

}  // namespace query_product_sales_report
