namespace query_search_books_by_criteria {

struct Book {
  int book_id;
  std::string title;
  std::string author;
  int year;
  std::string genre;
  double price;
};

struct BookFilters {
  std::optional<std::string> title_keyword;
  std::optional<int> min_year;
  std::optional<std::string> genre;
  std::optional<double> max_price;
};

/**
 * Function: Search for books based on multiple optional criteria.
 * 
 * @param filters Optional filters for title, year, genre, and price
 * @return List of books matching the criteria
 */
std::vector<Book> query_search_books_by_criteria(const BookFilters& filters) {
    auto conn = sqlgen::sqlite::connect("test_db.sqlite");

    // Start with base select from Book table
    auto query = sqlgen::select_from<Book>(
        sqlgen::col<"book_id">, 
        sqlgen::col<"title">, 
        sqlgen::col<"author">, 
        sqlgen::col<"year">, 
        sqlgen::col<"genre">, 
        sqlgen::col<"price">);

    // Build dynamic conditions
    using namespace sqlgen::transpilation::conditions;
    using namespace sqlgen::literals;

    auto condition = sqlgen::transpilation::make_condition(
        sqlgen::transpilation::conditions::equal(sqlgen::col<"book_id">, sqlgen::col<"book_id">));

    bool has_conditions = false;

    // Add title keyword filter
    if (filters.title_keyword.has_value()) {
        auto title_condition = sqlgen::col<"title">.like("%" + filters.title_keyword.value() + "%");
        if (!has_conditions) {
            condition = title_condition;
        } else {
            condition = condition && title_condition;
        }
        has_conditions = true;
    }

    // Add minimum year filter
    if (filters.min_year.has_value()) {
        auto year_condition = sqlgen::col<"year"> >= filters.min_year.value();
        if (!has_conditions) {
            condition = year_condition;
        } else {
            condition = condition && year_condition;
        }
        has_conditions = true;
    }

    // Add genre filter
    if (filters.genre.has_value()) {
        auto genre_condition = sqlgen::col<"genre"> == filters.genre.value();
        if (!has_conditions) {
            condition = genre_condition;
        } else {
            condition = condition && genre_condition;
        }
        has_conditions = true;
    }

