```cpp
#pragma once

#include <sqlgen/sqlite/connect.hpp>
#include <sqlgen/commit.hpp>
#include <string>

namespace schema_migration_add_column {

struct User {
  PrimaryKey<int> user_id;
  std::string username;
};

struct UserAfter {
  PrimaryKey<int, auto_incr> user_id;
  std::string username;
  std::string phone_number;
  bool is_active;
};

/**
 * Function: Perform schema migration to add new columns.
 * 
 * @return true if migration succeeds, false otherwise
 */
bool migration_add_column() {
  try {
    // Connect to the SQLite database
    auto connection_result = sqlgen::sqlite::connect("test_db.sqlite");

    if (!connection_result) {
      return false;
    }

    auto conn = connection_result.value();

    // Begin transaction for the migration
    auto transaction_result = conn->begin_transaction();

    if (!transaction_result) {
      return false;
    }

    auto transaction = transaction_result.value();

    try {
      // Execute ALTER TABLE statements to add the new columns
      auto stmt1 = R"(ALTER TABLE User ADD COLUMN phone_number VARCHAR(20))";
      auto result1 = transaction->execute(stmt1);

      if (!result1) {
        transaction->rollback();
        return false;
      }

      auto stmt2 = R"(ALTER TABLE User ADD COLUMN is_active INTEGER DEFAULT 1)";
      auto result2 = transaction->execute(stmt2);

      if (!result2) {
        transaction->rollback();
        return false;
      }

      // Commit the transaction
      auto commit_result = sqlgen::commit(transaction);

      return static_cast<bool>(commit_result);

    } catch (...) {
      transaction->rollback();
      return false;
    }

  } catch (...) {
    return false;
  }

  return true;
}

} // namespace schema_migration_add_column
