  };

  struct NotEqual {
    Operation op1;
    Operation op2;
  };

  struct NotLike {
    Operation op;
    dynamic::Value pattern;
  };

  struct NotIn {
    Operation op;
    std::vector<dynamic::Value> patterns;
  };

