#pragma once

#include <sqlgen/sqlite/connect.hpp>
#include <sqlgen/update.hpp>
#include <sqlgen/where.hpp>
#include <sqlgen/col.hpp>
#include <sqlgen/literals.hpp>

namespace update_order_status {

using namespace sqlgen::literals;

struct Order {
  int order_id;
  std::string status;
  std::string order_date;
  double total_amount;
};

int update_order_status() {
  // Connect to the SQLite database
  auto conn = sqlgen::sqlite::connect("test_db.sqlite");

  int total_rows_affected = 0;

  // Update pending orders older than 7 days to 'expired'
  auto pending_result = sqlgen::update<Order>(
      "status"_c.set("expired")
  ) | sqlgen::where(
      ("status"_c == "pending") && 
      ("order_date"_c < sqlgen::transpilation::Operation<
          sqlgen::transpilation::Operator::date_plus_duration,
          sqlgen::transpilation::Value<std::string>,
          rfl::Tuple<std::chrono::duration<int, std::ratio<86400>>> // 86400 seconds = 1 day
        >{
          .operand1 = sqlgen::transpilation::Value<std::string>("now"),
          .operand2 = rfl::Tuple<std::chrono::duration<int, std::ratio<86400>>>(std::chrono::duration<int, std::ratio<86400>>(-7))
        })
  );

  auto pending_execution = pending_result(conn);
  if (pending_execution) {
    total_rows_affected += pending_execution.value()->last_number_of_changes();
  }

  // Update shipped orders to 'delivered' (simulated)
  auto shipped_result = sqlgen::update<Order>(
      "status"_c.set("delivered")
  ) | sqlgen::where(
