namespace schema_create_view_sales_summary {

struct Product {
  PrimaryKey<int> product_id;
  std::string name;
  double price;
  int stock;
};

struct Sale {
  PrimaryKey<int, auto_incr> sale_id;
  int product_id;
  int quantity;
  double amount;
};

struct SalesSummary {
  static constexpr bool is_view = true;
  std::string product_name;
  int total_quantity;
  double total_revenue;
};

/**
 * Function: Create a view SalesSummary that aggregates sales by product.
 * 
 * @return true if view creation succeeds, false otherwise
 */
bool create_view_sales_summary() {
  auto conn = sqlite::connect("test_db.sqlite");
  if (!conn) {
    return false;
  }

  const auto query = select_from<Sale, "s">(
      as<"product_name">(col<"name", "p">()),
      sum(as<"total_quantity">(col<"quantity", "s">())),
