#pragma once

#include <sqlgen/read.hpp>
#include <sqlgen/sqlite/connect.hpp>
#include <sqlgen/joins.hpp>
#include <sqlgen/col.hpp>
#include <sqlgen/literals.hpp>

using namespace sqlgen::literals;

namespace right_join_departments_projects {

struct Department {
  int department_id;
  std::string name;
};

struct Project {
  int project_id;
  int department_id;
  std::string name;
};

struct DepProj {
  std::optional<std::string> department_name;
  std::string project_name;
};

/**
 * description: right_join_departments_projects.
 * This function demonstrates how to perform a right join between departments and projects using sqlgen read API.
 * It returns a vector of DepProj structs, where each struct contains the department name (if available) and the project name.
 * Returns: std::vector<DepProj>.
 */
std::vector<DepProj> right_join_departments_projects() {
  auto conn = sqlgen::sqlite::connect("test_db.sqlite");

  using namespace sqlgen;

  // Define columns with aliases for both tables
  constexpr auto dept_id_col = col<"department_id", "d">;
  constexpr auto dept_name_col = col<"name", "d">;
  constexpr auto proj_dept_id_col = col<"department_id", "p">;
  constexpr auto proj_name_col = col<"name", "p">;

  // Create the right join - all projects with their departments (if any)
  auto join_query = right_join<Project, "p">(
    dept_id_col == proj_dept_id_col
  );

  // Select the required fields for DepProj
  auto result = (read<std::vector<DepProj>> | where(proj_name_col.is_not_null())) 
    .operator()<decltype(join_query)>(conn);

  if (result) {
    return std::move(*result);
  } else {
    throw std::runtime_error("Failed to execute right join query: " + result.error());
  }
}

}  // namespace right_join_departments_projects
