namespace mathematical_operations_analysis {

struct Product {
  PrimaryKey<int> product_id;
  std::string name;
  double price;
  int quantity;
  double discount_rate;
};

struct MathAnalysis {
  int product_id;
  std::string name;
  double abs_price;
  double ceil_price;
  double floor_price;
  double rounded_price;
  double exp_discount;
  double ln_price;
  double log2_quantity;
  double sin_discount;
  double cos_discount;
  double tan_discount;
  double sqrt_quantity;
};

/**
 * Insert products into a temporary SQLite table and run a SELECT that computes
 * various mathematical expressions, returning results as std::vector<MathAnalysis>.
 */
std::vector<MathAnalysis> analyze_mathematical_operations(const std::vector<Product>& products) {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to SQLite database
  auto conn = sqlite::connect("test_db.sqlite");
  if (!conn) {
    return {};
  }

  // Create Product table
  const auto create_table_query = R"(
    CREATE TABLE IF NOT EXISTS Product (
      product_id INTEGER PRIMARY KEY,
      name TEXT NOT NULL,
      price REAL NOT NULL,
      quantity INTEGER NOT NULL,
      discount_rate REAL NOT NULL
    )
  )";

  if (auto res = conn->execute(create_table_query); !res) {
    return {};
  }

  // Clear existing data
  if (auto res = conn->execute("DELETE FROM Product"); !res) {
    return {};
  }

  // Insert products
  for (const auto& product : products) {
    const auto insert_query = R"(
      INSERT INTO Product (product_id, name, price, quantity, discount_rate)
      VALUES (?, ?, ?, ?, ?)
    )";

    if (auto res = conn->execute(insert_query, product.product_id, product.name, 
                                product.price, product.quantity, product.discount_rate); !res) {
      return {};
    }
  }

  // Perform mathematical operations using sqlgen
  auto result = select_from<"Product">(
    "product_id"_c,
    "name"_c,
    abs("price"_c) | as<"abs_price">,
    ceil("price"_c) | as<"ceil_price">,
    floor("price"_c) | as<"floor_price">,
    round("price"_c, 2) | as<"rounded_price">,
    exp("discount_rate"_c / 100.0) | as<"exp_discount">,
    ln("price"_c) | as<"ln_price">,
    log2("quantity"_c) | as<"log2_quantity">,
    sin("discount_rate"_c) | as<"sin_discount">,
    cos("discount_rate"_c) | as<"cos_discount">,
    tan("discount_rate"_c) | as<"tan_discount">,
    sqrt("quantity"_c) | as<"sqrt_quantity">
  ) | to<std::vector<MathAnalysis>>;

  auto math_results = result(conn);
  if (!math_results) {
    return {};
  }

  return std::move(*math_results);
}

}  // namespace mathematical_operations_analysis
