  }

  // Create temporary OrderItem table
  conn->execute(R"(
    CREATE TABLE IF NOT EXISTS OrderItem (
      item_id INTEGER PRIMARY KEY,
      order_id INTEGER NOT NULL,
      product_id INTEGER NOT NULL,
      unit_price REAL NOT NULL,
      quantity INTEGER NOT NULL,
      discount_rate REAL,
      tax_rate REAL
    )
  )").value();

  // Clear existing data
  conn->execute("DELETE FROM OrderItem").value();

  // Insert items into the table
  for (const auto& item : items) {
    conn->execute(
      "INSERT INTO OrderItem (item_id, order_id, product_id, unit_price, quantity, discount_rate, tax_rate) VALUES (?, ?, ?, ?, ?, ?, ?)",
      item.item_id.value(), item.order_id, item.product_id, item.unit_price, item.quantity,
      item.discount_rate.has_value() ? std::to_string(item.discount_rate.value()) : "NULL",
      item.tax_rate.has_value() ? std::to_string(item.tax_rate.value()) : "NULL"
    ).value();
