/**
 * description: replace_text_in_notes.
 * This function demonstrates how to replace text in notes using sqlgen update API.
 * It replaces all occurrences of "foo" with "bar" in the content column of the Note table.
 * Returns: std::vector<UpdatedNote>.
 */
std::vector<UpdatedNote> replace_text_in_notes() {
  // Connect to the SQLite database
  auto conn = sqlgen::sqlite::connect("test_db.sqlite");

  // Define columns using literals
  using namespace sqlgen::literals;
  constexpr auto note_id_col = "note_id"_c;
  constexpr auto content_col = "content"_c;

  // First, read all existing notes to return updated view
  auto original_notes = sqlgen::read<std::vector<Note>>(conn).value_or(std::vector<Note>{});

  // Perform the update operation: replace "foo" with "bar" in content column
  auto update_result = sqlgen::update<Note>(
      content_col.set(sqlgen::replace(content_col, std::string("foo"), std::string("bar")))
  )(conn);

  // Read the updated notes for verification
  auto updated_notes = sqlgen::read<std::vector<Note>>(conn).value_or(std::vector<Note>{});

  // Convert to UpdatedNote format for return
  std::vector<UpdatedNote> result;
  result.reserve(updated_notes.size());

  for (const auto& note : updated_notes) {
    result.push_back(UpdatedNote{
        .note_id = note.note_id,
        .updated_content = note.content
    });
  }

  return result;
}

}  // namespace replace_text_in_notes
