#pragma once

#include <sqlgen/cascade.hpp>
#include <sqlgen/create_table.hpp>
#include <sqlgen/delete_from.hpp>
#include <sqlgen/drop.hpp>
#include <sqlgen/insert.hpp>
#include <sqlgen/sqlite/connect.hpp>
