namespace cascade_delete_demo {

struct Parent {
  int parent_id;
  std::string name;
};

struct Child {
  int child_id;
  int parent_id;
  std::string note;
};

/**
 * Demonstrates cascade delete behavior in SQLite using foreign key constraints.
 * Returns: bool.
 */
bool cascade_delete_demo() {
  // Connect to SQLite database
  auto conn = sqlgen::sqlite::connect("test_db.sqlite");

  // Enable foreign key constraints
  conn = conn.and_then([](const auto& c) {
    return c->execute("PRAGMA foreign_keys = ON").transform([&](const auto&) { return c; });
  });

  // Drop tables if they exist
  conn = conn.and_then(sqlgen::drop<Child>.if_exists(true));
  conn = conn.and_then(sqlgen::drop<Parent>.if_exists(true));

  // Create Parent table
  conn = conn.and_then(sqlgen::create_table<Parent>);

  // Create Child table with cascade delete
  conn = conn.and_then([](const auto& c) {
    const auto query = 
      "CREATE TABLE Child ("
      "child_id INTEGER PRIMARY KEY, "
      "parent_id INTEGER, "
      "note TEXT, "
      "FOREIGN KEY (parent_id) REFERENCES Parent(parent_id) ON DELETE CASCADE"
      ")";
    return c->execute(query).transform([&](const auto&) { return c; });
  });

  // Insert parent record
  Parent parent{.parent_id = 1, .name = "Parent1"};
  conn = conn.and_then(sqlgen::insert(parent));

  // Insert child records
  Child child1{.child_id = 1, .parent_id = 1, .note = "Child1"};
  Child child2{.child_id = 2, .parent_id = 1, .note = "Child2"};
  std::vector<Child> children = {child1, child2};
  conn = conn.and_then(sqlgen::insert(children));

  // Verify children were inserted
  int child_count_before = 0;
  conn = conn.and_then([&](const auto& c) {
    return c->execute("SELECT COUNT(*) FROM Child WHERE parent_id = 1")
      .and_then([](const auto& result) {
        return result.transform([](const auto& rows) -> int {
          if (!rows.empty()) {
            return std::stoi(rows[0][0]);
          }
          return 0;
        });
      })
      .transform([&](int count) {
        child_count_before = count;
        return c;
      });
  });

  // Delete parent
  conn = conn.and_then(
    sqlgen::delete_from<Parent> | sqlgen::where(sqlgen::eq<&Parent::parent_id>(1))
  );

  // Check if children were automatically deleted
  int child_count_after = 0;
  conn = conn.and_then([&](const auto& c) {
    return c->execute("SELECT COUNT(*) FROM Child WHERE parent_id = 1")
      .and_then([](const auto& result) {
        return result.transform([](const auto& rows) -> int {
          if (!rows.empty()) {
            return std::stoi(rows[0][0]);
          }
          return 0;
        });
      })
      .transform([&](int count) {
        child_count_after = count;
        return c;
      });
  });

  // Return true if cascade delete worked (children were deleted automatically)
  return child_count_before == 2 && child_count_after == 0;
}

}  // namespace cascade_delete_demo
