    auto verify_update = sqlgen::update<Account>(
        "balance"_c.set(2000.0)
    ) | sqlgen::where("account_id"_c == 1 && "status"_c == "premium");

    auto verify_result = verify_update(*conn);
    if (!verify_result) {
      return false;
    }

    return true;
  } catch (...) {
    return false;
  }
}

}  // namespace update_set_operations
