  using TableType = T;
};

template <size_t _i, class T>
struct GetTableType<std::integral_constant<size_t, _i>, T> {
  using TableType = T;
};

template <class Alias, class T>
using get_table_t = typename GetTableType<std::remove_cvref_t<Alias>,
