};

/**
 * Description: This function retrieves the top products based on total sales.
 * Returns: std::vector<TopProduct>.
 */
std::vector<TopProduct> get_top_products(size_t limit_count = 10) {
    sqlite3* db;
    std::vector<TopProduct> result;

    // Open database connection
    int rc = sqlite3_open("test_db.sqlite", &db);
    if (rc != SQLITE_OK) {
        sqlite3_close(db);
        return result;
    }

    // Prepare SQL statement with parameterized limit
    std::string sql = "SELECT p.product_id, p.product_name, p.category, SUM(p.price * s.quantity) as total_sales "
                      "FROM Product p "
                      "INNER JOIN Sales s ON p.product_id = s.product_id "
                      "GROUP BY p.product_id, p.product_name, p.category "
                      "ORDER BY total_sales DESC "
                      "LIMIT ?;";

    sqlite3_stmt* stmt;
    rc = sqlite3_prepare_v2(db, sql.c_str(), -1, &stmt, nullptr);
    if (rc != SQLITE_OK) {
        sqlite3_close(db);
        return result;
    }

    // Bind limit parameter
    sqlite3_bind_int(stmt, 1, static_cast<int>(limit_count));

    // Execute query and fetch results
    while ((rc = sqlite3_step(stmt)) == SQLITE_ROW) {
        TopProduct product;
        product.product_id = sqlite3_column_int(stmt, 0);
        product.product_name = reinterpret_cast<const char*>(sqlite3_column_text(stmt, 1));
        product.category = reinterpret_cast<const char*>(sqlite3_column_text(stmt, 2));
        product.total_sales = sqlite3_column_double(stmt, 3);
        result.push_back(product);
    }

    // Clean up
    sqlite3_finalize(stmt);
    sqlite3_close(db);

    return result;
}

}  // namespace get_top_products
