using namespace sqlgen::literals;

namespace weekday_sales_analysis {

struct Sales {
  PrimaryKey<int> sale_id;
  int product_id;
  int quantity;
  Timestamp<"%Y-%m-%d %H:%M:%S"> sale_time;
};

struct WeekdayStats {
  int weekday;
  int total_quantity;
};

/**
 * Description: This function analyzes sales data to calculate total quantity sold for each weekday.
 * Returns: std::vector<WeekdayStats>.
 */
std::vector<WeekdayStats> weekday_sales_analysis() {
  auto conn = sqlgen::sqlite::connect("test_db.sqlite");

  auto result = sqlgen::select_from<Sales>(
      sqlgen::weekday(Sales::sale_time) | sqlgen::as<"weekday">,
      sqlgen::sum(Sales::quantity) | sqlgen::as<"total_quantity">
  ) | sqlgen::group_by(sqlgen::weekday(Sales::sale_time))
    | sqlgen::to<std::vector<WeekdayStats>>
    | conn;

  if (result) {
    return std::move(*result);
  } else {
    return {};
  }
}

}  // namespace weekday_sales_analysis
