#pragma once

#include <sqlgen/sqlite/connect.hpp>
#include <sqlgen/select_from.hpp>
#include <sqlgen/group_by.hpp>
#include <sqlgen/aggregations.hpp>
#include <sqlgen/as.hpp>
#include <sqlgen/internal/collect/vector.hpp>
#include <sqlgen/literals.hpp>

using namespace sqlgen;
using namespace sqlgen::literals;

namespace group_by_with_aggregations {

struct User {
  PrimaryKey<int> user_id;
  std::string name;
};

struct Post {
  PrimaryKey<int> post_id;
  int user_id;
  std::string content;
};

struct Stats {
  PrimaryKey<int> user_id;
  std::string name;
  int post_count;
  std::optional<double> avg_length;
};

/**
 * Description: This function retrieves user statistics including post count and average post length.
 * Returns: std::vector<Stats>.
 */
std::vector<Stats> group_by_with_aggregations() {
  auto conn = sqlite::connect("test_db.sqlite");

  using namespace sqlgen::literals;

  const auto user_id_col = "user_id"_c;
  const auto name_col = "name"_c;
  const auto content_col = "content"_c;

  const auto post_count_alias = sqlgen::as<"post_count">;
  const auto avg_length_alias = sqlgen::as<"avg_length">;

  auto result = select_from<User, Post>(
      user_id_col,
      name_col,
      count() | post_count_alias,
      avg(length(content_col)) | avg_length_alias
  ) 
  | join<Post>(user_id_col == Post::user_id_col)
  | group_by(user_id_col, name_col)
  | to<std::vector<Stats>>
  | conn;

  if (!result) {
    throw std::runtime_error(result.error().what());
  }

  return std::move(*result);
}

}  // namespace group_by_with_aggregations
